import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])

    # Fenwick Tree implementation
    tree = [0] * (n + 2)
    arr = [1] * (n + 1)  # 1-indexed array for actual values

    def fenwick_update(idx, delta):
        while idx <= n + 1:
            tree[idx] += delta
            idx += idx & (-idx)

    def fenwick_query(idx):
        result = 0
        while idx > 0:
            result += tree[idx]
            idx -= idx & (-idx)
        return result

    def range_sum(l, r):
        if l > r:
            return 0
        return fenwick_query(r + 1) - fenwick_query(l)

    # Initialize Fenwick tree with value 1 at each position
    for i in range(1, n + 1):
        fenwick_update(i, 1)

    index = 2
    results = []

    for _ in range(q):
        op = data[index]
        l = int(data[index + 1])
        r = int(data[index + 2])
        index += 3

        if op == "QUERY":
            result = range_sum(l, r)
            results.append(str(result))
        else:
            delta = -1 if op == "ALLOCATE" else 1
            for i in range(l, r + 1):
                old_val = arr[i]
                arr[i] += delta
                fenwick_update(i, delta)

    print("\n".join(results))

if __name__ == "__main__":
    main()
